#!/usr/bin/env bash
set -euo pipefail

if [ -z "${BW_SESSION:-}" ] || ! bw status 2>/dev/null | grep -q unlocked; then
  export BW_SESSION=$(bw unlock --raw)
fi

cmd=${1:-list}
shift || true

case "$cmd" in
  get)    bw get password "$1" ;;
  user)   bw get username "$1" ;;
  totp)   bw get totp "$1" ;;
  search) bw list items --search "$1" | jq '.[] | {name, login: .login.username}' ;;
  sync)   bw sync ;;
  *) echo "usage: $0 {get|user|totp|search|sync} <item>"; exit 1 ;;
esac
